// @FIGURE_CODE_BEGIN
var W = 620, H = 348;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

/* ── geometry constants ─────────────────────────────────────────────── */
var r = 16, d = 2 * r, hRow = r * Math.sqrt(3);
var ROWS = 7, COLS = 8;
var bw = 272, bh = 2 * r + (ROWS - 1) * hRow;
var cx0 = 22, cy0 = 14;          // crystalline block origin
var ax0 = 326, ay0 = 14;         // amorphous block origin
var DX = ax0 - cx0;
var crysC = cx0 + bw / 2, amorC = ax0 + bw / 2;
var capY = cy0 + bh + 34;

var ORANGE = '#E8863C', YELLOW = '#FFC61A';

/* ── layers ─────────────────────────────────────────────────────────── */
var gBg = draw.group();
var gSpheres = draw.group();
var gGuides = draw.group();
var gSel = draw.group();
var gLabels = draw.group();
var gRead = draw.group();
var gLegend = draw.group();

gBg.rect(W, H).move(0, 0).fill('#ffffff').on('click', function () { clearSelection(); });

/* ── sphere gradient (smooth shaded teal, no hard rim) ──────────────── */
var grad = draw.gradient('radial', function (add) {
  add.stop(0.00, '#8fd4ce');
  add.stop(0.30, '#5cb6b2');
  add.stop(0.62, '#3a9a99');
  add.stop(1.00, '#227e82');
});
grad.attr({ cx: 0.36, cy: 0.31, r: 0.78, fx: 0.33, fy: 0.28 });

/* ── deterministic RNG ──────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rnd = mulberry32(20481);

/* ── build crystalline lattice ──────────────────────────────────────── */
var crystal = [];
for (var j = 0; j < ROWS; j++) {
  for (var i = 0; i < COLS; i++) {
    crystal.push({
      x: cx0 + r + i * d + (j % 2 ? r : 0),
      y: cy0 + r + j * hRow,
      panel: 'crystal'
    });
  }
}

/* ── build amorphous packing: same count-per-area, jittered + relaxed ─ */
var amorph = [];
(function buildAmorph() {
  var cand = [];
  for (var j2 = 0; j2 < ROWS; j2++) {
    var rowShift = (rnd() - 0.5) * 0.7 * r;
    for (var i2 = 0; i2 < COLS; i2++) {
      cand.push({
        x: ax0 + r + i2 * d + (j2 % 2 ? r : 0) + rowShift + (rnd() - 0.5) * 0.62 * r,
        y: ay0 + r + j2 * hRow + (rnd() - 0.5) * 0.60 * r,
        panel: 'amorphous'
      });
    }
  }
  // remove only 3 spheres so both blocks read as equally dense
  for (var k = 0; k < 3; k++) cand.splice(Math.floor(rnd() * cand.length), 1);
  amorph = cand;
})();
(function relax() {
  var minSep = d * 1.0;
  var xmin = ax0 + r - 2, xmax = ax0 + bw - r + 2;
  var ymin = ay0 + r - 2, ymax = ay0 + bh - r + 2;
  for (var k = 0; k < 160; k++) {
    for (var a = 0; a < amorph.length; a++) {
      for (var b = a + 1; b < amorph.length; b++) {
        var pa = amorph[a], pb = amorph[b];
        var dx = pb.x - pa.x, dy = pb.y - pa.y;
        var dd = Math.sqrt(dx * dx + dy * dy);
        if (dd > minSep) continue;
        if (dd < 1e-6) { dx = 0.4; dy = 0.2; dd = 0.45; }
        var push = (minSep - dd) / 2, ux = dx / dd, uy = dy / dd;
        pa.x -= ux * push; pa.y -= uy * push;
        pb.x += ux * push; pb.y += uy * push;
      }
    }
    for (var m = 0; m < amorph.length; m++) {
      var p = amorph[m];
      p.x = Math.max(xmin, Math.min(xmax, p.x));
      p.y = Math.max(ymin, Math.min(ymax, p.y));
    }
  }
})();

var spheres = crystal.concat(amorph);

/* ── draw spheres ───────────────────────────────────────────────────── */
spheres.forEach(function (p) {
  var c = gSpheres.circle(d).center(p.x, p.y).fill(grad)
    .stroke({ color: '#1f7176', width: 0.5, opacity: 0.16 });
  c.css('cursor', 'pointer');
  p.el = c;
  c.on('mousemove', function (e) {
    showTooltip(p.panel === 'crystal'
      ? 'Crystalline particle — click to see its neighbours'
      : 'Amorphous particle — click to see its neighbours', e);
  });
  c.on('mouseleave', hideTooltip);
  c.on('click', function (e) { e.stopPropagation(); selectSphere(p, true); });
});

/* ── captions ───────────────────────────────────────────────────────── */
function label(g, str, x, y, size, fill, anchor) {
  var t = g.plain(str);
  t.font({ family: 'sans-serif', size: size, fill: fill, anchor: anchor || 'middle' });
  t.attr({ x: x, y: y });
  return t;
}
label(gLabels, 'Crystalline', crysC, capY, 20, '#1a1a1a');
label(gLabels, 'Amorphous', amorC, capY, 20, '#1a1a1a');

/* ── guide-line families derived from the real lattice ──────────────── */
function families(pts, angDeg, minCount) {
  var th = angDeg * Math.PI / 180;
  var ux = Math.cos(th), uy = Math.sin(th), nx = -uy, ny = ux;
  var arr = pts.map(function (p) {
    return { off: p.x * nx + p.y * ny, t: p.x * ux + p.y * uy };
  }).sort(function (a, b) { return a.off - b.off; });
  var out = [], grp = [];
  function flush() {
    if (grp.length >= minCount) {
      var offs = 0, tmin = Infinity, tmax = -Infinity;
      grp.forEach(function (o) { offs += o.off; tmin = Math.min(tmin, o.t); tmax = Math.max(tmax, o.t); });
      var off = offs / grp.length;
      tmin -= 1.3 * r; tmax += 1.3 * r;
      out.push({
        x1: ux * tmin + nx * off, y1: uy * tmin + ny * off,
        x2: ux * tmax + nx * off, y2: uy * tmax + ny * off
      });
    }
    grp = [];
  }
  for (var i = 0; i < arr.length; i++) {
    if (grp.length && Math.abs(arr[i].off - grp[0].off) > 3) flush();
    grp.push(arr[i]);
  }
  flush();
  return out;
}
var rowLines = families(crystal, 0, 4);
var diagLines = families(crystal, 60, 4).concat(families(crystal, -60, 4));

var guideMode = 'Off';
function drawGuideSet(lines) {
  lines.forEach(function (L) {
