function families(pts, angDeg, minCount) {
  var th = angDeg * Math.PI / 180;
  var ux = Math.cos(th), uy = Math.sin(th), nx = -uy, ny = ux;
  var arr = pts.map(function (p) {
    return { off: p.x * nx + p.y * ny, t: p.x * ux + p.y * uy };
  }).sort(function (a, b) { return a.off - b.off; });
  var out = [], grp = [];
  function flush() {
    if (grp.length >= minCount) {
      var offs = 0, tmin = Infinity, tmax = -Infinity;
      grp.forEach(function (o) { offs += o.off; tmin = Math.min(tmin, o.t); tmax = Math.max(tmax, o.t); });
      var off = offs / grp.length;
      tmin -= 1.3 * r; tmax += 1.3 * r;
      out.push({
        x1: ux * tmin + nx * off, y1: uy * tmin + ny * off,
        x2: ux * tmax + nx * off, y2: uy * tmax + ny * off
      });
    }
    grp = [];
  }
  for (var i = 0; i < arr.length; i++) {
    if (grp.length && Math.abs(arr[i].off - grp[0].off) > 3) flush();
    grp.push(arr[i]);
  }
  flush();
  return out;
}
var rowLines = families(crystal, 0, 4);
var diagLines = families(crystal, 60, 4).concat(families(crystal, -60, 4));

var guideMode = 'Off';
function drawGuideSet(lines) {
  lines.forEach(function (L) {
    gGuides.line(L.x1, L.y1, L.x2, L.y2)
      .stroke({ color: ORANGE, width: 1.7, linecap: 'round', opacity: 0.95 });
    gGuides.line(L.x1 + DX, L.y1, L.x2 + DX, L.y2)
      .stroke({ color: ORANGE, width: 1.5, linecap: 'round', opacity: 0.6 })
      .attr('stroke-dasharray', '6,5');
  });
}
function drawLegend() {
  gLegend.clear();
  if (guideMode === 'Off') return;
  var y = 332;
  gLegend.line(crysC - 108, y - 4, crysC - 88, y - 4).stroke({ color: ORANGE, width: 1.7 });
  label(gLegend, 'passes through every centre', crysC - 82, y, 10.5, '#666', 'start');
  gLegend.line(amorC - 108, y - 4, amorC - 88, y - 4)
    .stroke({ color: ORANGE, width: 1.5, opacity: 0.6 }).attr('stroke-dasharray', '6,5');
  label(gLegend, 'same lines — centres miss them', amorC - 82, y, 10.5, '#666', 'start');
}
function toggle_latticeGuides(mode) {
  guideMode = mode;
  gGuides.clear();
  if (mode === 'Rows' || mode === 'Rows + diagonals') drawGuideSet(rowLines);
  if (mode === 'Rows + diagonals') drawGuideSet(diagLines);
  drawLegend();
  var el = document.getElementById('latticeGuidesInput');
  if (el && el.value !== mode) el.value = mode;
}

/* ── neighbourhood analysis + selection ─────────────────────────────── */
var showShells = true;
var selected = null;

function neighboursOf(p) {
  var cut = d * 1.16, out = [];
  spheres.forEach(function (q) {
    if (q === p || q.panel !== p.panel) return;
    var dd = Math.hypot(q.x - p.x, q.y - p.y);
    if (dd < cut) out.push({ q: q, d: dd });
  });
  out.sort(function (a, b) { return a.d - b.d; });
  return out;
}

function toggle_shells(on) { showShells = on; if (selected) selectSphere(selected, false); }

function clearSelection() {
  selected = null;
  gSel.clear();
  gRead.clear();
  hideTooltip();
}

function selectSphere(p, doPopup) {
  selected = p;
  gSel.clear();
  gRead.clear();
  var nb = neighboursOf(p);
  var ds = nb.map(function (o) { return o.d / d; });
  var mn = ds.length ? Math.min.apply(null, ds) : 0;
  var mx = ds.length ? Math.max.apply(null, ds) : 0;
  var mean = ds.length ? ds.reduce(function (a, b) { return a + b; }, 0) / ds.length : 1;
  var spread = mean ? (mx - mn) / mean * 100 : 0;

  if (showShells && ds.length) {
    gSel.circle(2 * mean * d).center(p.x, p.y).fill('none')
      .stroke({ color: '#c96a18', width: 1.2, opacity: 0.85 }).attr('stroke-dasharray', '4,4');
    gSel.circle(2 * mean * d * Math.sqrt(3)).center(p.x, p.y).fill('none')
      .stroke({ color: '#c96a18', width: 1, opacity: 0.38 }).attr('stroke-dasharray', '3,5');
  }
  nb.forEach(function (o) {
    gSel.circle(d + 2).center(o.q.x, o.q.y).fill('none')
      .stroke({ color: '#F08A24', width: 2.4 });
  });
  gSel.circle(d + 5).center(p.x, p.y).fill('none')
    .stroke({ color: YELLOW, width: 3 });

  /* readout chip (below the caption, clear of the block) */
  var isC = p.panel === 'crystal';
  var cxp = isC ? crysC : amorC;
  gRead.rect(272, 40).move(cxp - 136, 264).radius(6)
    .fill('#ffffff').stroke({ color: '#dfe5e5', width: 1 });
  label(gRead, (isC ? 'Crystalline' : 'Amorphous') + ' · ' + nb.length + ' touching neighbours',
    cxp, 280, 11.5, '#222');
  var l2 = (isC && spread < 1)
    ? 'all at exactly ' + mean.toFixed(2) + ' d — every particle alike'
    : 'distances ' + mn.toFixed(2) + '–' + mx.toFixed(2) + ' d · spread ' + spread.toFixed(0) + '%';
  label(gRead, l2, cxp, 296, 10.5, '#666');

  if (doPopup) {
    if (isC) {
      showPopup('Crystalline neighbourhood',
        'This particle touches ' + nb.length + ' neighbours, all sitting exactly on the first distance ring. ' +
        'Pick any other particle in this block and you get the identical picture — that exact repetition, ' +
        'continued over long distances, is what makes the solid crystalline.');
    } else {
      showPopup('Amorphous neighbourhood',
        'This particle touches ' + nb.length + ' neighbours at distances from ' + mn.toFixed(2) + ' to ' +
        mx.toFixed(2) + ' diameters, so they straddle the ring instead of landing on it. ' +
        'The packing density is essentially the same as the crystal, but the arrangement changes from ' +
        'particle to particle, so there is no long-range order.');
    }
  }
}

/* ── demo-step player ───────────────────────────────────────────────── */
function nearestTo(list, x, y) {
  var best = list[0], bd = Infinity;
  list.forEach(function (p) {
    var dd = Math.hypot(p.x - x, p.y - y);
    if (dd < bd) { bd = dd; best = p; }
  });
  return best;
}
var demoCrystal = nearestTo(crystal, cx0 + bw / 2, cy0 + bh / 2);
var demoAmorph = nearestTo(amorph, ax0 + bw / 2, ay0 + bh / 2);

var steps = [
  {
    title: 'Two solids, same particles', guides: 'Off', pick: null,
    narration: 'Both blocks contain identical spheres packed to essentially the same density. The only difference is where each sphere sits.'
  },
  {
    title: 'Draw the rows', guides: 'Rows', pick: null,
    narration: 'Row guides on: in the crystalline block every line runs cleanly through a whole row of sphere centres, while the same lines on the amorphous side slice through gaps and clip spheres at random.'
  },
  {
    title: 'Add the diagonals', guides: 'Rows + diagonals', pick: null,
    narration: 'Two more families of lines appear at ±60°. In the crystal they also thread sphere centres all the way across — the pattern repeats in several directions at once. No such direction exists in the amorphous solid.'
  },
  {
    title: 'Zoom in on one particle', guides: 'Off', pick: 'crystal',
    narration: 'Guides off. A sphere in the crystal is selected: six touching neighbours (orange) sit exactly on the first distance ring. Click other crystal spheres — the picture repeats identically.'
  },
  {
    title: 'The same test on the glass', guides: 'Off', pick: 'amorphous',
    narration: 'The same test on the amorphous block: the neighbour count varies (four, five, six) and neighbours straddle the ring instead of landing on it. Short-range packing is similar, but it never repeats.'
  }
];
var step = 0;

function applyStep(i) {
  step = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[step];
  toggle_latticeGuides(s.guides);
  if (s.pick === 'crystal') selectSphere(demoCrystal, false);
  else if (s.pick === 'amorphous') selectSphere(demoAmorph, false);
  else clearSelection();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (step + 1) + '/' + steps.length + ' · ' + s.title;
}
function nextStep() { applyStep(step + 1); }
function prevStep() { applyStep(step - 1); }

/* ── init ───────────────────────────────────────────────────────────── */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Crystalline solids repeat the same particle arrangement over long distances, while amorphous solids have the same local packing density but no repeating long-range order.
KEY INSIGHT (what students should walk away understanding): Both solids look locally similar — it is the repetition of that local arrangement over long distances that makes a solid crystalline, and its absence that makes a solid amorphous.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
