<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 620, H = 358;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H).attr('preserveAspectRatio', 'xMidYMid meet');

/* ── geometry constants ─────────────────────────────────────────────── */
var r = 16, d = 2 * r, hRow = r * Math.sqrt(3);
var ROWS = 8, COLS = 7;
var bw = (COLS - 1) * d + 2 * r + r;          // 240 (odd rows overhang by r)
var bh = 2 * r + (ROWS - 1) * hRow;           // ~226
var cx0 = 26, cy0 = 14;                       // crystalline block origin
var ax0 = 354, ay0 = 14;                      // amorphous block origin
var DX = ax0 - cx0;
var crysC = cx0 + bw / 2, amorC = ax0 + bw / 2;
var capY = cy0 + bh + 32;

var ORANGE = '#E8863C', YELLOW = '#FFC61A';

/* ── layers ─────────────────────────────────────────────────────────── */
var gBg = draw.group();
var gFrame = draw.group();
var gSpheres = draw.group();
var gGuides = draw.group();
var gSel = draw.group();
var gLabels = draw.group();
var gRead = draw.group();
var gLegend = draw.group();

gBg.rect(W, H).move(0, 0).fill('#ffffff').on('click', function () { clearSelection(); });

/* very subtle panel frames (kept near-invisible so the figure stays faithful) */
[[cx0, cy0], [ax0, ay0]].forEach(function (o) {
  gFrame.rect(bw + 8, bh + 8).move(o[0] - 4, o[1] - 4).radius(6)
    .fill('none').stroke({ color: '#eef3f3', width: 1 });
});

/* ── sphere gradient (smooth shaded teal, no hard rim) ──────────────── */
var grad = draw.gradient('radial', function (add) {
  add.stop(0.00, '#93d3cf');
  add.stop(0.30, '#5bb2af');
  add.stop(0.62, '#379594');
  add.stop(1.00, '#217a7d');
});
grad.attr({ cx: 0.36, cy: 0.31, r: 0.78, fx: 0.33, fy: 0.28 });

/* ── deterministic RNG ──────────────────────────────────────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
var rnd = mulberry32(90731);

/* ── crystalline lattice: perfect close-packed offset rows ──────────── */
var crystal = [];
for (var j = 0; j < ROWS; j++) {
  for (var i = 0; i < COLS; i++) {
    crystal.push({
      x: cx0 + r + i * d + (j % 2 ? r : 0),
      y: cy0 + r + j * hRow,
      panel: 'crystal'
    });
  }
}

/* ── amorphous packing: same size block, same density, no long-range order
      Built as jittered rows, then relaxed with BOTH an overlap push and a
      spring back to each particle's own target site. The spring is what
      stops the relaxation from opening a large central void — particles can
      shuffle locally but the block stays evenly filled edge to edge.       */
var amorph = [];
(function buildAmorph() {
  var cand = [];
  for (var j2 = 0; j2 < ROWS; j2++) {
    var rowShift = (rnd() - 0.5) * 0.55 * r;        // whole-row slip (motif rotation proxy)
    for (var i2 = 0; i2 < COLS; i2++) {
      var hx = ax0 + r + i2 * d + (j2 % 2 ? r : 0) + rowShift;
      var hy = ay0 + r + j2 * hRow;
      cand.push({
        x: hx + (rnd() - 0.5) * 0.95 * r,
        y: hy + (rnd() - 0.5) * 0.80 * r,
        panel: 'amorphous'
      });
    }
  }
  /* remove a handful of spheres for irregular voids — never two adjacent,
     so the density stays comparable to the crystal everywhere. */
  var removed = [], tries = 0;
  while (removed.length < 6 && tries < 600) {
    tries++;
    var k = Math.floor(rnd() * cand.length);
    if (removed.indexOf(k) >= 0) continue;
    var ok = true;
    for (var m = 0; m < removed.length; m++) {
      var a = cand[k], b = cand[removed[m]];
      if (Math.hypot(a.x - b.x, a.y - b.y) < 2.6 * d) { ok = false; break; }
    }
    if (ok) removed.push(k);
  }
  removed.sort(function (p, q) { return q - p; });
  removed.forEach(function (k) { cand.splice(k, 1); });
  cand.forEach(function (p) { p.tx = p.x; p.ty = p.y; });
  amorph = cand;
})();
(function relax() {
  var minSep = d * 0.985;
  var xmin = ax0 + r - 1, xmax = ax0 + bw - r + 1;
  var ymin = ay0 + r - 1, ymax = ay0 + bh - r + 1;
  for (var k = 0; k < 60; k++) {
    for (var a = 0; a < amorph.length; a++) {
      for (var b = a + 1; b < amorph.length; b++) {
        var pa = amorph[a], pb = amorph[b];
        var dx = pb.x - pa.x, dy = pb.y - pa.y;
        var dd = Math.sqrt(dx * dx + dy * dy);
        if (dd > minSep) continue;
        if (dd < 1e-6) { dx = 0.4; dy = 0.2; dd = 0.45; }
        var push = (minSep - dd) * 0.35, ux = dx / dd, uy = dy / dd;
        pa.x -= ux * push; pa.y -= uy * push;
        pb.x += ux * push; pb.y += uy * push;
      }
    }
    for (var m = 0; m < amorph.length; m++) {
      var p = amorph[m];
      p.x += (p.tx - p.x) * 0.10;                  // anti-void spring
      p.y += (p.ty - p.y) * 0.10;
      p.x = Math.max(xmin, Math.min(xmax, p.x));
      p.y = Math.max(ymin, Math.min(ymax, p.y));
    }
  }
})();

var spheres = crystal.concat(amorph);

/* ── draw spheres ───────────────────────────────────────────────────── */
spheres.forEach(function (p) {
  var c = gSpheres.circle(d).center(p.x, p.y).fill(grad)
    .stroke({ color: '#1f7176', width: 0.5, opacity: 0.16 });
  c.css('cursor', 'pointer');
  p.el = c;
  c.on('mousemove', function (e) {
    showTooltip(p.panel === 'crystal'
      ? 'Crystalline particle — click to see its neighbours'
      : 'Amorphous particle — click to see its neighbours', e);
  });
  c.on('mouseleave', hideTooltip);
  c.on('click', function (e) { e.stopPropagation(); selectSphere(p, true); });
});

/* ── captions ───────────────────────────────────────────────────────── */
function label(g, str, x, y, size, fill, anchor) {
  var t = g.plain(str);
  t.font({ family: 'sans-serif', size: size, fill: fill, anchor: anchor || 'middle' });
  t.attr({ x: x, y: y });
  return t;
}
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return t;
}
halo(label(gLabels, 'Crystalline', crysC, capY, 20, '#1a1a1a'));
halo(label(gLabels, 'Amorphous', amorC, capY, 20, '#1a1a1a'));

/* ── guide-line families derived from the real lattice ──────────────── */
function families(pts, angDeg, minCount) {
  var th = angDeg * Math.PI / 180;
  var ux = Math.cos(th), uy = Math.sin(th), nx = -uy, ny = ux;
  var arr = pts.map(function (p) {
    return { off: p.x * nx + p.y * ny, t: p.x * ux + p.y * uy };
  }).sort(function (a, b) { return a.off - b.off; });
  var out = [], grp = [];
  function flush() {
    if (grp.length >= minCount) {
      var offs = 0, tmin = Infinity, tmax = -Infinity;
      grp.forEach(function (o) { offs += o.off; tmin = Math.min(tmin, o.t); tmax = Math.max(tmax, o.t); });
      var off = offs / grp.length;
      tmin -= 1.2 * r; tmax += 1.2 * r;
      out.push({
        x1: ux * tmin + nx * off, y1: uy * tmin + ny * off,
        x2: ux * tmax + nx * off, y2: uy * tmax + ny * off
      });
    }
    grp = [];
  }
  for (var i = 0; i < arr.length; i++) {
    if (grp.length && Math.abs(arr[i].off - grp[0].off) > 3) flush();
    grp.push(arr[i]);
  }
  flush();
  return out;
}
var rowLines = families(crystal, 0, 4);
var diagLines = families(crystal, 60, 4).concat(families(crystal, -60, 4));

var guideMode = 'Off';
function drawGuideSet(lines) {
  lines.forEach(function (L) {
    gGuides.line(L.x1, L.y1, L.x2, L.y2)
      .stroke({ color: ORANGE, width: 1.7, linecap: 'round', opacity: 0.95 });
    gGuides.line(L.x1 + DX, L.y1, L.x2 + DX, L.y2)
      .stroke({ color: ORANGE, width: 1.5, linecap: 'round', opacity: 0.6 })
      .attr('stroke-dasharray', '6,5');
  });
}
function drawLegend() {
  gLegend.clear();
  if (guideMode === 'Off') return;
  var y = 346;
  var x = 60;
  gLegend.line(x, y - 4, x + 22, y - 4).stroke({ color: ORANGE, width: 1.7 });
